export type ExecutiveCoverageMetric = MetricPlan & {
  implemented: boolean;
  verified: boolean;
  productionAccepted: boolean;
  businessAccepted: boolean;
  available: boolean;
  recordLink: string | null;
  queryCost: "unestimated";
  freshness: "unverified";
  sourceFields: string[];
};

export type ExecutiveModuleCoverage = {
  moduleId: string;
  moduleName: string;
  accessBoundary: string;
  requiredMetrics: number;
  implementedMetrics: number;
  status: "unavailable" | "partial" | "implemented";
  implemented: boolean;
  verified: boolean;
  productionAccepted: boolean;
  businessAccepted: boolean;
  available: boolean;
  reason: string | null;
  metrics: ExecutiveCoverageMetric[];
};

const registeredMetricIds = new Set<string>(metricIds);
// Manage ERPX is the Platform operations shell. Its Executive data plane is already
// represented by the dedicated platform_administration module in this 32-domain plan.
const coveredModuleRegistry = moduleRegistry.filter(({ id }) => id !== "manage_erpx");
const registryModuleIds = new Set(coveredModuleRegistry.map(({ id }) => id));
if (Object.keys(plan).length !== registryModuleIds.size || [...registryModuleIds].some((id) => !(id in plan))) {
  throw new Error("EXECUTIVE_COVERAGE_MUST_MATCH_MODULE_REGISTRY");
}

/** Business and production gates stay false until separately reviewed evidence is recorded. */
export function executiveCoverage(): ExecutiveModuleCoverage[] {
  return coveredModuleRegistry.map((module) => {
    const modulePlan: ModulePlan = plan[module.id as keyof typeof plan];
    const plannedMetrics: MetricPlan[] = modulePlan.metrics;
    const metrics: ExecutiveCoverageMetric[] = plannedMetrics.map((metric) => ({
      ...metric,
      implemented: metric.implementation === "platform-executive" || !!metric.implementedMetric && registeredMetricIds.has(metric.implementedMetric),
      verified: false,
      productionAccepted: false,
      businessAccepted: false,
      available: false,
      recordLink: null,
      queryCost: "unestimated",
      freshness: "unverified",
      sourceFields: [],
    }));
    const implementedMetrics = metrics.filter((metric) => metric.implemented).length;
    const status = implementedMetrics === metrics.length ? "implemented" : implementedMetrics ? "partial" : "unavailable";
    return {
      moduleId: module.id,
      moduleName: module.name,
      accessBoundary: modulePlan.accessBoundary,
      requiredMetrics: metrics.length,
      implementedMetrics,
      status,
      implemented: implementedMetrics === metrics.length,
      verified: false,
      productionAccepted: false,
      businessAccepted: false,
      available: false,
      reason: implementedMetrics < metrics.length
        ? "Additional metric adapters are not implemented."
        : "Executive reconciliation, production acceptance and business acceptance are not recorded.",
      metrics,
    };
  });
}
